import React, { createContext, useContext, useState, useEffect } from 'react'

const AuthContext = createContext(null)

export const useAuth = () => useContext(AuthContext)

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const savedUser = localStorage.getItem('aurachat_user')
    if (savedUser) {
      try {
        setUser(JSON.parse(savedUser))
      } catch (e) {
        console.error('Error parsing user session', e)
      }
    }
    setLoading(false)
  }, [])

  const login = (email, password) => {
    // Generate a fixed profile ID for the user based on email (e.g. hash or uuid-like string)
    const profileId = 'usr_' + Math.abs(email.split('').reduce((a, b) => {
      a = ((a << 5) - a) + b.charCodeAt(0)
      return a & a
    }, 0)).toString(36)

    const userData = { email, profileId, name: email.split('@')[0] }
    localStorage.setItem('aurachat_user', JSON.stringify(userData))
    setUser(userData)
    return { success: true }
  }

  const register = (email, password, name) => {
    const profileId = 'usr_' + Math.abs(email.split('').reduce((a, b) => {
      a = ((a << 5) - a) + b.charCodeAt(0)
      return a & a
    }, 0)).toString(36)

    const userData = { email, profileId, name: name || email.split('@')[0] }
    localStorage.setItem('aurachat_user', JSON.stringify(userData))
    setUser(userData)
    return { success: true }
  }

  const loginWithGoogle = () => {
    // Simulate OAuth Login
    const randomSuffix = Math.floor(100 + Math.random() * 900)
    const mockEmail = `google.user.${randomSuffix}@gmail.com`
    const profileId = 'usr_g' + Math.random().toString(36).substr(2, 9)
    const userData = { email: mockEmail, profileId, name: `Google User ${randomSuffix}` }

    localStorage.setItem('aurachat_user', JSON.stringify(userData))
    setUser(userData)
    return { success: true }
  }

  const logout = () => {
    localStorage.removeItem('aurachat_user')
    setUser(null)
  }

  return (
    <AuthContext.Provider value={{ user, loading, login, register, loginWithGoogle, logout }}>
      {!loading && children}
    </AuthContext.Provider>
  )
}

export default AuthProvider
